-- Library v4. Replaces matching slugs. Does not archive replaced templates and does not touch job AHAs.

alter table public.aha_library
  add column if not exists archived boolean not null default false;

alter table public.project_ahas
  add column if not exists products jsonb not null default '[]'::jsonb,
  add column if not exists extra_ppe text[] not null default '{}';

alter table public.projects
  add column if not exists site_address_override text not null default '',
  add column if not exists nearest_hospital text not null default '',
  add column if not exists occupational_clinic text not null default '',
  add column if not exists emergency_contacts jsonb not null default '[]'::jsonb,
  add column if not exists muster_point text not null default '';

do $$
declare
  r record;
begin
  for r in
    select nsp.nspname, rel.relname, con.conname
    from pg_constraint con
    join pg_class rel on rel.oid = con.conrelid
    join pg_namespace nsp on nsp.oid = rel.relnamespace
    where nsp.nspname = 'public'
      and rel.relname in ('aha_library', 'project_ahas')
      and con.contype = 'c'
      and pg_get_constraintdef(con.oid) ilike '%scope%'
  loop
    execute format('alter table %I.%I drop constraint %I', r.nspname, r.relname, r.conname);
  end loop;
end $$;

alter table public.aha_library
  add constraint aha_library_scope_check
  check (scope in ('paint', 'wallcovering', 'access', 'general'));

alter table public.project_ahas
  add constraint project_ahas_scope_check
  check (scope in ('paint', 'wallcovering', 'access', 'general'));

insert into public.aha_library (slug, name, scope, csi, considerations, equipment_rows, competent_persons, steps)
values
  ('jobsite-basics', 'Jobsite basics (every job)', 'general', '01 35 00', '[]'::jsonb, '[{"id":"baa6684b-992d-4c37-9db4-ec776278e232","equipment":"Hand tools","training":"Authorized to use","inspection":"Inspect daily for broken or loose parts; red-tag and replace defects"},{"id":"89e8c3b3-2ab9-4734-b2b7-f999382e2151","equipment":"Power tools","training":"Authorized to use; trained per manufacturer","inspection":"Inspect before each use; guards in place; red-tag defects"},{"id":"a1fbc0a4-1968-4e80-bc68-09e6ffc4c32e","equipment":"Extension cords / GFCI","training":"Authorized to use","inspection":"Inspect before each use; test GFCI; no tape repairs"},{"id":"4978c338-ef6a-4386-a1ed-4767d2bfaf50","equipment":"Standard PPE (hard hat, safety glasses, cut-resistant gloves, hi-vis vest, work boots)","training":"PPE use and care","inspection":"Inspect daily; replace damaged PPE immediately"}]'::jsonb, '[{"id":"efbc3baf-5f72-4ebd-a140-502cf8ce7f09","activity":"Supervise safety on the job site","qualification":"competent","na":false,"note":"","employee":""},{"id":"f4f39ad2-1b30-4dac-b5a2-f7d54e8a8f35","activity":"First aid / CPR","qualification":"trained","na":false,"note":"","employee":""}]'::jsonb, '[{"name":"Site-specific training and orientation","hazards":["Workers untrained on site hazards or the task","Scope changes not reviewed"],"controls":["Complete the GC site orientation before starting work","Review this JHA with the crew and collect signatures before work begins","Review again when new crew members join","Stop and amend the JHA with the Safety Department if the scope or conditions change"],"osha_refs":"1926.21","em385_refs":"","prob":"S","sev":"M"},{"name":"Daily pre-task plan","hazards":["Crews and trades working without a shared plan","Changing conditions missed"],"controls":["Foreman reviews the day''s tasks, hazards, and controls with the crew before starting","Coordinate work areas and sequencing with other trades and the GC superintendent","Document the huddle per company and GC requirements","Anyone can stop work for an unsafe condition"],"osha_refs":"1926.21","em385_refs":"","prob":"S","sev":"M"},{"name":"Wear required PPE","hazards":["Head, eye, hand, or foot injury","Hearing damage"],"controls":["Hard hat, safety glasses, cut-resistant gloves, hi-vis vest, and work boots at all times","Hearing protection when noise exceeds 85 dBA","Goggles or face shield when the task or SDS requires","No loose clothing or jewelry that can snag","Replace damaged PPE immediately"],"osha_refs":"1926.95 · 1926.100 · 1926.102 · 1926.52","em385_refs":"","prob":"S","sev":"M"},{"name":"Enter the site and walk the work area","hazards":["Slips, trips, and falls","Floor openings and unprotected edges","Overhead work by other trades"],"controls":["Walk the route and work area at the start of each shift","Keep a clear path of travel and clear exits","Report uncovered openings or missing guardrails to the GC; do not work until protected","Never remove hole covers or guardrails","Stay clear of overhead work, pinch points, and moving equipment"],"osha_refs":"1926.25 · 1926.34 · 1926.502(i)","em385_refs":"","prob":"O","sev":"M"},{"name":"Receive and store materials","hazards":["Pinch and crush injuries","Struck by delivery vehicles or forklifts","Material falling from stacks"],"controls":["Stay clear of moving equipment and heed backup alarms","Stack material stable, level, and at a safe height","Stage close to the point of use in approved laydown areas","Keep material away from floor openings and edges","Store flammables only in approved storage"],"osha_refs":"1926.250 · 1926.152","em385_refs":"","prob":"O","sev":"M"},{"name":"Lift, carry, and move materials","hazards":["Strains and sprains","Striking others","Spills"],"controls":["Team lift heavy or awkward loads","Use carts, dollies, and handling aids whenever possible","Balance the load and watch your path","Never move material above other workers","Seal paint and liquids before moving","Do not stand in front of or above a wall or floor opening while stocking"],"osha_refs":"1926.250","em385_refs":"","prob":"L","sev":"M"},{"name":"Inspect tools before use","hazards":["Defective tools","Missing or bypassed guards","Electric shock"],"controls":["Inspect before each use; tag and remove defective tools from the site","Never remove, bypass, or modify guards or safety devices","Use tools only as intended and per the manufacturer","GFCI protection on every circuit serving tools"],"osha_refs":"1926.300 · 1926.404(b)","em385_refs":"","prob":"S","sev":"R"},{"name":"Extension cords and temporary power","hazards":["Electric shock or electrocution","Trips on cords"],"controls":["Hard- or extra-hard-usage cords; factory-assembled sets where possible","No cords with cuts, worn insulation, exposed conductors, or missing ground prongs","No tape repairs; send damaged cords for repair or disposal","GFCI on every cord","Elevate cords or route them out of walkways and doorways"],"osha_refs":"1926.404(b) · 1926.405(g)","em385_refs":"","prob":"S","sev":"R"},{"name":"Work around other trades","hazards":["Hazardous noise","Dust and fumes from other work","Struck by materials or equipment"],"controls":["Ear plugs from 85 to 115 dBA; plugs and muffs above 115 dBA","Coordinate sequencing with the GC to avoid stacked trades","Keep unprotected workers out of areas where coatings give off hazardous fumes","Barricade your work area when others pass through"],"osha_refs":"1926.52 · 1926.55","em385_refs":"","prob":"O","sev":"M"},{"name":"Housekeeping and cleanup","hazards":["Slips, trips, and falls","Dust","Lacerations"],"controls":["Clean as you go and at the end of each shift","Store equipment out of travel paths; stack material in the laydown area","Sweeping compound or HEPA vacuum; no dry sweeping or compressed air on dust","Blades and sharps in a closed container"],"osha_refs":"1926.25 · 1926.1153","em385_refs":"","prob":"O","sev":"M"},{"name":"Emergency response and first aid","hazards":["Delayed response to an injury or fire"],"controls":["Crew knows the site address, emergency contacts, and muster point","First aid kit and a trained person on site","Crew knows where fire extinguishers are","Report every injury and near miss to the foreman immediately"],"osha_refs":"1926.50 · 1926.150","em385_refs":"","prob":"S","sev":"R"}]'::jsonb),
  ('occupied-spaces', 'Work in occupied spaces', 'general', '01 35 00', '["public_exposure"]'::jsonb, '[{"id":"5e63e8d6-93e7-4e7f-a1d4-ef5bb7542bae","equipment":"Barricades & signage","training":"Site-specific orientation","inspection":"Check daily; replace damaged signs"},{"id":"9d1963a8-755b-4413-8ebf-02db9017f25d","equipment":"Floor protection","training":"Authorized to use","inspection":"Check edges are taped down each shift"},{"id":"2aefe23f-7457-41a6-b73e-69ab3713479b","equipment":"Fans / air scrubbers","training":"Authorized to use","inspection":"Inspect cords and filters before use"}]'::jsonb, '[]'::jsonb, '[{"name":"Coordinate with tenant and building","hazards":["Occupants entering the work area","Odor complaints and work stoppages"],"controls":["Schedule with the building manager; after-hours for high-odor or disruptive work","Post notice to occupants before work starts","Confirm access, elevator use, and loading dock times","Know the building''s emergency procedures and alarm signals"],"osha_refs":"1926.20","em385_refs":"","prob":"O","sev":"M"},{"name":"Isolate and barricade the work area","hazards":["Occupants contacting wet paint, ladders, or tools","Blocked exits"],"controls":["Barricade and sign the work area","Keep exits, corridors, and fire equipment clear at all times","Never leave ladders, lifts, or open containers unattended","Wet paint signs until dry"],"osha_refs":"1926.200 · 1926.34","em385_refs":"","prob":"O","sev":"M"},{"name":"Control odors, dust, and vapors","hazards":["Vapors or dust migrating into occupied areas and HVAC"],"controls":["Low- or zero-VOC products where specified","Coordinate HVAC shutdown or return-air protection with the building engineer","Ventilate to the exterior; negative air where required","HEPA vacuum cleanup; no dry sweeping"],"osha_refs":"1926.55","em385_refs":"","prob":"O","sev":"M"},{"name":"Protect finishes and fire systems","hazards":["Overspray on finishes and furniture","Covered smoke detectors or sprinkle