  ('active-facility', 'Work in active industrial facility', 'general', '01 35 00', '["energized_loto","work_permits"]'::jsonb, '[{"id":"55842142-91f0-41ef-a904-bf4eaaf5a608","equipment":"High-visibility vests","training":"Owner site orientation","inspection":"Daily"},{"id":"2aedc094-d107-4682-8482-e5813abee0e2","equipment":"Barricades","training":"Owner site orientation","inspection":"Check daily"},{"id":"faaee6cd-e89e-4bf8-96ab-388360421096","equipment":"Owner lockout devices","training":"LOTO awareness; owner performs lockout","inspection":"Verify owner lockout before each task"}]'::jsonb, '[{"id":"f923b85c-0181-437d-83d4-fda0ee07e661","activity":"Supervise safety on the job site","qualification":"competent","na":false,"note":"","employee":""}]'::jsonb, '[{"name":"Owner orientation and permits","hazards":["Unknown site hazards","Working without required permits"],"controls":["Complete the owner''s safety orientation before starting","Obtain required permits (hot work, lift, confined space, line break)","Follow owner PPE rules, which may exceed ours","Know the facility alarm signals and muster point"],"osha_refs":"1926.21","em385_refs":"","prob":"O","sev":"M"},{"name":"Work near operating equipment","hazards":["Moving parts and stored energy","Hot surfaces and pipes"],"controls":["Owner-performed lockout before work on or near equipment; verify zero energy","Never operate owner equipment or valves","Keep clear of moving conveyors, robots, and machinery","Treat pipes and surfaces as hot until confirmed"],"osha_refs":"1910.147 · 1926.417","em385_refs":"","prob":"S","sev":"C"},{"name":"Forklift and vehicle traffic","hazards":["Struck-by"],"controls":["Hi-vis vests at all times","Barricade the work zone; use a spotter near traffic lanes","Coordinate traffic routes and work hours with the facility","Make eye contact with operators before crossing"],"osha_refs":"1926.200 · 1910.178","em385_refs":"","prob":"O","sev":"R"},{"name":"Protect product and equipment","hazards":["Overspray or dust on product and equipment"],"controls":["Mask and cover equipment below and around work","Coordinate shutdowns and area turnover with the facility","No spraying near air intakes without approval"],"osha_refs":"Site requirements","em385_refs":"","prob":"O","sev":"N"},{"name":"Housekeeping and egress","hazards":["Blocked exits and aisles","Trips"],"controls":["Keep aisles, exits, and fire equipment clear","Stage materials only in approved areas"],"osha_refs":"1926.25 · 1926.34","em385_refs":"","prob":"O","sev":"M"}]'::jsonb),
  ('heat-illness', 'Heat illness prevention', 'general', '01 35 00', '["health_hazards"]'::jsonb, '[{"id":"3c6ca0f7-fc5e-4048-bdec-da32af9ae3c0","equipment":"Drinking water (at least 1 qt per worker per hour)","training":"Heat illness prevention","inspection":"Check supply at start of shift and through the day"},{"id":"e824c8c2-ad14-4f2e-b8af-630a8013c7aa","equipment":"Shade / cool-down area","training":"Heat illness prevention","inspection":"In place before temperatures exceed 80°F"},{"id":"413f6c9b-d076-465b-b09f-0a4a7cbd05b4","equipment":"Fans / cooling","training":"Authorized to use","inspection":"Inspect cords before use"}]'::jsonb, '[]'::jsonb, '[{"name":"Provide water, shade, and rest","hazards":["Heat exhaustion","Heat stroke"],"controls":["Fresh, cool water available all shift, close to the work","Shade or cool-down area when temperatures exceed 80°F (outdoors) or per the indoor heat plan","Encourage preventative cool-down breaks; never discourage breaks","High-heat procedures above 95°F: observation, reminders, and crew check-ins"],"osha_refs":"Cal/OSHA T8 §3395 · §3396","em385_refs":"","prob":"O","sev":"R"},{"name":"Acclimatize and monitor the crew","hazards":["New or returning workers at higher risk"],"controls":["Close observation of new workers during their first 14 days","Buddy system during high heat","Schedule the heaviest work for cooler hours where possible"],"osha_refs":"Cal/OSHA T8 §3395","em385_refs":"","prob":"S","sev":"R"},{"name":"Respond to heat illness symptoms","hazards":["Delayed response to heat stroke"],"controls":["Crew knows the signs: dizziness, confusion, heavy or no sweating, nausea","Move the worker to shade and begin cooling; do not leave them alone","Call 911 for confusion, collapse, or no improvement","Crew knows the site address and directions for emergency services"],"osha_refs":"Cal/OSHA T8 §3395","em385_refs":"","prob":"S","sev":"C"}]'::jsonb),
  ('flammable-storage', 'Flammable material storage', 'general', '01 35 00', '["hazmat_waste"]'::jsonb, '[{"id":"111a400e-8755-4760-b4cb-395c897f69fc","equipment":"Flammable storage cabinet","training":"HazCom / SDS","inspection":"Doors close and latch; labeled; inspected weekly"},{"id":"f83b44db-504e-472d-a06e-577574dde1ed","equipment":"Approved safety cans","training":"HazCom / SDS","inspection":"Inspect lids and flame arrestors before use"},{"id":"3a81877f-911e-42c7-8833-4e09d429b681","equipment":"Fire extinguisher","training":"Extinguisher use","inspection":"Charged, tagged, and accessible; inspected monthly"}]'::jsonb, '[]'::jsonb, '[{"name":"Store flammable and combustible liquids","hazards":["Fire","Vapor buildup"],"controls":["Store in approved cabinets or a designated storage area approved by the GC","No more than 25 gal of flammable liquids in a room outside approved cabinets","Never store in exits, stairways, or near ignition sources","Keep containers closed and labeled","No smoking signs posted; extinguisher at the storage area"],"osha_refs":"1926.152 · 1926.150","em385_refs":"","prob":"S","sev":"C"},{"name":"Dispense and transfer","hazards":["Static ignition","Spills"],"controls":["Transfer only in ventilated areas away from ignition sources","Bond and ground metal containers during transfer","Use approved safety cans for portable quantities","Keep absorbent on hand"],"osha_refs":"1926.152","em385_refs":"","prob":"S","sev":"R"},{"name":"Waste, rags, and empty containers","hazards":["Spontaneous combustion of oily rags","Improper disposal"],"controls":["Oily and solvent rags in a closed metal can; empty daily","Label and store waste per project and local requirements","Never pour solvents or paint into drains"],"osha_refs":"1926.152 · 1926.252","em385_refs":"","prob":"S","sev":"R"}]'::jsonb),
  ('confined-space', 'Confined spaces (tanks, pits, vaults)', 'general', '01 35 00', '["confined_space","respiratory","work_permits"]'::jsonb, '[{"id":"38a58fce-b31b-4ad6-ba66-fd05d4c8957f","equipment":"Gas monitor (O2, LEL, CO, H2S)","training":"Trained in use; calibrated per manufacturer","inspection":"Bump test before each use"},{"id":"6ec0f79e-a9fd-49ef-b09b-28d68d567fe3","equipment":"Ventilation blower","training":"Authorized to use","inspection":"Inspect before use"},{"id":"12b5777b-18a2-436f-af79-f2872407631b","equipment":"Retrieval system / tripod","training":"Entrant and attendant training","inspection":"Inspect before each use"}]'::jsonb, '[{"id":"a9cece55-af57-42ae-b074-5ee527e97fa0","activity":"Confined space evaluation and entry supervision","qualification":"competent","na":false,"note":"","employee":""}]'::jsonb, '[{"name":"Evaluate the space","hazards":["Entering a permit-required space without controls"],"controls":["No entry into any tank, pit, vault, or enclosed space until evaluated by a competent person","Permit-required spaces entered only under a written permit program","If the owner or GC controls the space, follow their permit and coordinate entry"],"osha_refs":"1926.1203","em385_refs":"","prob":"S","sev":"C"},{"name":"Test and ventilate the atmosphere","hazards":["Oxygen deficiency","Flammable or toxic vapors from coatings"],"controls":["Test oxygen, flammability, and toxics before entry and continuously during work","Continuous forced-air ventilation while coating","Only products reviewed for confined-space use (check SDS)","Supplied-air respirator where required by the permit or SDS"],"osha_refs":"1926.1203 · 1926.1204 · 1910.134","em385_refs":"","prob":"S","sev":"C"},{"name":"Entry, attendant, and rescue","hazards":["Delayed rescue"],"controls":["Trained attendant outside at all times with communication to entrants","Rescue plan and equipment in place before entry","Never enter to rescue without proper equipment; call rescue services"],"o