  ('ladders', 'Ladders', 'access', '01 54 00', '["falls_elevation"]'::jsonb, '[{"id":"2eebaca9-9ad4-4243-9f44-46f2dbff9524","equipment":"Stepladders and extension ladders","training":"Ladder safety training; documentation provided","inspection":"Inspect for defects before each use; red-tag defects"}]'::jsonb, '[{"id":"8868a40a-1334-4a7c-810b-148eb0caee22","activity":"Ladder inspections","qualification":"competent","na":false,"note":"Inspected by user before each use","employee":""}]'::jsonb, '[{"name":"Select the right ladder","hazards":["Ladder failure","Overreaching from a ladder that is too short"],"controls":["Type I or IA duty rating; no Type III (light duty) ladders","Fiberglass when working near electrical","Tall enough to work without standing on the top step or the top 3 rungs","Never exceed the duty rating (worker plus tools and material)"],"osha_refs":"1926.1053(a)","em385_refs":"","prob":"S","sev":"R"},{"name":"Inspect the ladder","hazards":["Defective ladder"],"controls":["Inspect rails, rungs, feet, spreaders, and locks before each use","Keep ladders clean of paint, oil, and mud","Red-tag and remove defective ladders until repaired or replaced"],"osha_refs":"1926.1053(b)","em385_refs":"","prob":"S","sev":"R"},{"name":"Set up the ladder","hazards":["Ladder slipping or tipping","Struck by people, doors, or vehicles"],"controls":["Firm, level footing; never on boxes, buckets, or loose material","Stepladders fully open and locked; never lean a closed stepladder","Extension ladders at 4:1, extended 36 in. above the landing, secured top and bottom","Not in front of a door unless it is locked, blocked, or guarded","Barricade or post a helper in traffic areas","At least 10 ft from overhead power lines"],"osha_refs":"1926.1053(b)","em385_refs":"","prob":"S","sev":"R"},{"name":"Climb and work from the ladder","hazards":["Falls","Dropped tools striking workers below"],"controls":["Face the ladder and keep 3 points of contact while climbing","Carry tools in a pouch or raise them with a line","Keep your belt buckle between the rails; move the ladder instead of overreaching","Do not stand on the top step, top cap, or top 3 rungs of an extension ladder","Do not straddle to another object or push and pull hard enough to shift the ladder","One person on the ladder at a time"],"osha_refs":"1926.1053(b)","em385_refs":"","prob":"S","sev":"R"}]'::jsonb),
  ('rolling-scaffold', 'Rolling scaffolds (Baker / Perry)', 'access', '01 54 00', '["falls_elevation","rolling_scaffolds"]'::jsonb, '[{"id":"de11febc-fe74-4463-9f13-df2a88d1a23a","equipment":"Rolling scaffold","training":"Scaffold certification required for all users; documentation provided","inspection":"Inspect on delivery and before each shift by a competent person; green tag; red-tag defects"}]'::jsonb, '[{"id":"12ea26db-fda8-429e-b940-ce0ca8800609","activity":"Rolling / mobile scaffold inspection","qualification":"competent","na":false,"note":"Used by certified operator","employee":""},{"id":"9e2beb2e-fc33-4cda-81f1-99a3abcc9c3d","activity":"Scaffold inspection","qualification":"competent","na":false,"note":"Inspected by user before each use","employee":""}]'::jsonb, '[{"name":"Inspect and tag","hazards":["Defective or incomplete scaffold"],"controls":["Competent person inspects before each shift; initial and date the green tag","Red-tag missing, damaged, or mismatched parts until repaired","Only trained users on the scaffold"],"osha_refs":"1926.451(f) · T8 §1646","em385_refs":"","prob":"S","sev":"R"},{"name":"Set up the scaffold","hazards":["Racking or collapse","Tip-over"],"controls":["All diagonal and horizontal bracing in place; scaffold square","Guardrails (top rail about 42 in. plus midrail) and full-width planking","Outriggers where the height-to-base ratio requires","Check the floor for openings, slopes, cords, and debris before setup"],"osha_refs":"1926.452(w)","em385_refs":"","prob":"S","sev":"R"},{"name":"Work from the platform","hazards":["Falls","Dropped tools","Overloading"],"controls":["Wheels locked and scaffold immobilized while working","Climb only the built-in ladder or access frame; never the cross braces","No ladders, buckets, or planks on the platform to gain height","Stay within the rated load","Keep the area below clear; toeboards or barricades where others pass"],"osha_refs":"1926.451 · 1926.452(w)","em385_refs":"","prob":"S","sev":"R"},{"name":"Move the scaffold","hazards":["Tip-over","Striking overhead objects or openings"],"controls":["Clear the path and check overhead before moving","Push at or near the base; never pull from the platform","Riders only as allowed under T8 §1646(i)–(j); otherwise no one on the platform while moving","Secure tools and materials before moving"],"osha_refs":"T8 §1646 · 1926.452(w)(6)","em385_refs":"","prob":"S","sev":"R"}]'::jsonb),
  ('fixed-scaffold', 'Fixed (frame) scaffolds', 'access', '01 54 00', '["falls_elevation","fixed_scaffolds"]'::jsonb, '[{"id":"9339a5b2-1764-40fb-a6f7-42b0ed1fb08d","equipment":"Frame scaffold","training":"Scaffold user training; erectors trained under a competent person","inspection":"Inspect before each shift by a competent person; tagged"}]'::jsonb, '[{"id":"2724dede-8413-4f37-9454-eb5a3e3ad1cd","activity":"Supervise scaffold erection / dismantlement","qualification":"competent","na":false,"note":"If needed","employee":""},{"id":"1c3a33bf-1337-4370-b6eb-71bd4ea239b0","activity":"Scaffold inspection","qualification":"competent","na":false,"note":"Inspected by user before each use","employee":""}]'::jsonb, '[{"name":"Erect or accept the scaffold","hazards":["Improper erection","Collapse"],"controls":["Erect, alter, or dismantle only under a competent person","Use a GC or scaffold-contractor scaffold only after it is inspected and tagged","Base plates and mudsills on firm footing; ties per height requirements","Fully planked with gaps no more than 1 in.; planks overlap at least 12 in."],"osha_refs":"1926.451","em385_refs":"","prob":"S","sev":"C"},{"name":"Access the scaffold","hazards":["Falls while climbing"],"controls":["Use built-in ladders or stair towers","Never climb cross braces","3 points of contact; raise tools with a line or bucket"],"osha_refs":"1926.451(e)","em385_refs":"","prob":"S","sev":"R"},{"name":"Work on the scaffold","hazards":["Falls","Dropped objects"],"controls":["Top rail 42 in. ±3 in., midrail, and toeboards at least 3.5 in.","Personal fall arrest where guardrails are not feasible","Tether tools; bag or bucket materials up and down","No horseplay; keep platforms clear of debris and spilled paint"],"osha_refs":"1926.451(g)(h) · 1926.502","em385_refs":"","prob":"S","sev":"R"},{"name":"Weather and end of shift","hazards":["Wind","Slippery platforms"],"controls":["No work in high wind or storms","Clear water, paint, and debris from platforms before use"],"osha_refs":"1926.451(f)","em385_refs":"","prob":"S","sev":"M"}]'::jsonb),
