  ('openings-edges', 'Floor openings, shafts & leading edges', 'access', '01 54 00', '["falls_elevation"]'::jsonb, '[{"id":"7aef9006-498a-4feb-825e-5e7e39327e1a","equipment":"Personal fall protection system","training":"Trained in donning and use before starting work","inspection":"Inspect before each use; SRL-LE (ANSI Z359.14) for leading edge; red-tag defects"}]'::jsonb, '[{"id":"ee7f23c7-2c81-466a-8a1c-9fe8fec2c8ee","activity":"Fall protection supervision / inspection of fall protection equipment","qualification":"competent","na":false,"note":"Inspected by user before each use","employee":""},{"id":"eeeffea1-c70c-4eb9-8f55-96d8ac3f80e4","activity":"Fall protection plan development / anchors","qualification":"qualified","na":false,"note":"If needed","employee":""}]'::jsonb, '[{"name":"Identify openings and edges","hazards":["Falls through openings or from edges"],"controls":["Walk the area and identify openings, shafts, skylights, and edges 6 ft or more above a lower level","Report missing covers or guardrails to the GC; do not work until protected","Never remove covers or rails; if removal is needed, get GC approval and protect the opening"],"osha_refs":"1926.501 · 1926.502(i)","em385_refs":"","prob":"S","sev":"C"},{"name":"Work near unprotected edges","hazards":["Falls causing serious injury or death"],"controls":["Guardrail, safety net, or personal fall arrest at 6 ft or more","Fall arrest limits arresting force to 1,800 lb, free fall to 6 ft, and deceleration to 3.5 ft, with no contact with a lower level","Anchors rated 5,000 lb per worker or designed by a qualified person","SRL-LE rated for leading edge (ANSI Z359.14) where lines cross an edge","Inspect equipment before each use; rescue plan in place"],"osha_refs":"1926.502(d)","em385_refs":"","prob":"S","sev":"C"},{"name":"Prevent dropped objects","hazards":["Tools or material falling on workers below"],"controls":["Tether tools; toeboards or debris nets at edges","Barricade the area below","Never throw material down"],"osha_refs":"1926.502(j)","em385_refs":"","prob":"S","sev":"R"}]'::jsonb),
